<?php require_once __DIR__.'/../../includes/bootstrap.php';$u=require_login();if($_SERVER['REQUEST_METHOD']!=='POST') redirect('user/bookings/index.php');verify_csrf($_POST['csrf']??'');$id=(int)$_POST['booking_id'];$s=db()->prepare('SELECT * FROM vw_booking_summary WHERE id=? AND user_id=?');$s->execute([$id,$u['id']]);$b=$s->fetch();if(!$b||$b['status']!=='confirmed') exit('Invalid booking.');$s=db()->prepare('INSERT INTO booking_change_requests(booking_id,requested_by,reason,proposed_start_at,proposed_end_at,proposed_venue_id) VALUES(?,?,?,?,?,?)');$s->execute([$id,$u['id'],trim($_POST['reason']),$_POST['start_at']?:null,$_POST['end_at']?:null,($_POST['venue_id']??'')?:null]);audit('change_request_submitted','booking',$id);flash('success','Change request submitted for management review.');redirect('user/bookings/view.php?id='.$id);
